import pandas as pd
import itertools
import numpy as np

def task_func(animals=None, foods=None):
    default_animals = ['Dog', 'Cat', 'Bird']
    default_foods = ['Meat', 'Fish', 'Seeds']

    animals_missing = animals is None or len(animals) == 0
    foods_missing = foods is None or len(foods) == 0

    if animals_missing and foods_missing:
        return pd.DataFrame()

    if animals_missing:
        animals = default_animals
    if foods_missing:
        foods = default_foods

    combinations = list(itertools.product(animals, foods))
    np.random.shuffle(combinations)

    row_order = []
    col_order = []

    for animal, food in combinations:
        if animal not in row_order:
            row_order.append(animal)
        if food not in col_order:
            col_order.append(food)

    df = pd.DataFrame(index=row_order, columns=col_order)

    for animal, food in combinations:
        df.loc[animal, food] = f"{animal}:{food}"

    return df
